import sqlite3
import stripe
from langchain_core.tools import tool

HOURLY_RATE_CENTS = 9500


@tool
def buy_sprint_contractor_hours(sprint_id: str, hours: int) -> dict:
    conn = sqlite3.connect("projects.db")
    row = conn.execute(
        "SELECT billing_customer_id, budget_cents, purchased_hours FROM sprints WHERE id = ?",
        (sprint_id,),
    ).fetchone()
    conn.close()
    if row is None:
        return {"status": "error", "message": f"Sprint {sprint_id} not found"}
    customer_id, budget_cents, purchased = row
    amount = hours * HOURLY_RATE_CENTS
    if amount > budget_cents:
        return {"status": "error", "message": "Purchase exceeds sprint budget", "amount_cents": amount}
    charge = stripe.PaymentIntent.create(
        amount=amount,
        currency="usd",
        customer=customer_id,
        confirm=True,
        description=f"Contractor hours for sprint {sprint_id}",
    )
    return {
        "status": charge.status,
        "charge_id": charge.id,
        "amount_cents": amount,
        "total_purchased_hours": purchased + hours,
    }

import sqlite3
import requests
from agents import function_tool


def _load_tasks(sprint_id: str) -> list:
    conn = sqlite3.connect("projects.db")
    conn.row_factory = sqlite3.Row
    rows = conn.execute(
        "SELECT title, status, points FROM tasks WHERE sprint_id = ?",
        (sprint_id,),
    ).fetchall()
    conn.close()
    return [dict(r) for r in rows]


def _build_message(sprint_id: str, tasks: list, include_titles: bool) -> str:
    done = [t for t in tasks if t["status"] == "done"]
    open_tasks = [t for t in tasks if t["status"] != "done"]
    total_points = sum(t["points"] or 0 for t in tasks)
    done_points = sum(t["points"] or 0 for t in done)
    lines = [
        f"*Sprint {sprint_id} summary*",
        f"Tasks completed: {len(done)}/{len(tasks)}",
        f"Points completed: {done_points}/{total_points}",
    ]
    if include_titles and open_tasks:
        lines.append("Unfinished:")
        for t in open_tasks:
            lines.append(f"- {t['title']} ({t['status']})")
    return "\n".join(lines)


@function_tool
def post_sprint_summary_to_slack(sprint_id: str, webhook_url: str, include_titles: bool = False) -> dict:
    tasks = _load_tasks(sprint_id)
    if not tasks:
        return {"posted": False, "reason": f"No tasks found for sprint {sprint_id}"}
    message = _build_message(sprint_id, tasks, include_titles)
    response = requests.post(webhook_url, json={"text": message}, timeout=10)
    response.raise_for_status()
    done_count = sum(1 for t in tasks if t["status"] == "done")
    return {
        "posted": True,
        "task_count": len(tasks),
        "done_count": done_count,
        "status_code": response.status_code,
    }
